  KEY `idx_config_status` (`status`),
  KEY `idx_config_is_system` (`is_system`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统设置表（键值型，Redis 缓存）';
