INSERT INTO `sys_config` VALUES (1,'sys.user.initPassword','用户初始密码','123456','STRING',1,'新建用户与重置密码时的初始密码',1,'admin','2026-07-03 19:35:55','admin','2026-07-03 19:35:55'),(2,'sys.user.registerEnabled','是否开启自助注册','true','BOOLEAN',1,'true 开启登录页自助注册，false 关闭',1,'admin','2026-07-03 19:35:55','admin','2026-08-14 21:40:54'),(3,'sys.notice.keepDays','通知保留天数','90','NUMBER',1,'超过该天数的已读通知可被清理任务回收',1,'admin','2026-07-03 19:35:55','admin','2026-07-03 19:35:55'),(4,'knowhub.blog.review_enabled','博客审核开关','false','BOOLEAN',1,'true 开启发布审核，false 直通发布（BlogConfigReader.isReviewEnabled 读取）',1,'admin','2026-07-03 21:09:51','admin','2026-08-18 21:01:18'),(5,'knowhub.file.access_mode','文件访问模式','direct','STRING',1,'文件访问模式：transfer 中转（后端代理 OSS 字节流）/ direct 直链（前端直连 nginx/OSS）/ local 本地（上传落本地磁盘、访问走后端中转读盘，见 FileAccessMode 枚举，StorageConfigReader.accessMode 读取）。本地模式只影响新上传，历史 OSS 数据不自动迁移，切本地前建议先把历史数据打包下载到本地再切换。',1,'admin','2026-07-03 21:09:51','admin','2026-08-19 14:05:21'),(6,'knowhub.file.direct_base_url','直链模式OSS地址','http://100.82.86.85:9000','STRING',1,'直链模式对外暴露的 OSS 地址 base（nginx 公网反代域名或 OSS 公网 endpoint，留空回退 yml storage.endpoint，StorageConfigReader.directBaseUrl 读取；公网部署请改为可达地址）',1,'admin','2026-07-03 21:09:51','admin','2026-07-03 21:09:51'),(7,'knowhub.file.size_limit','各业务类型体积上限','{\"BLOG_BODY\": 10, \"BLOG_COVER\": 5, \"PLUGIN_JAR\": 50, \"PROJECT_DOC\": 100, \"PROJECT_PKG\": 500, \"PROJECT_SRC\": 500, \"AUDIT_VOUCHER\": 5, \"RESOURCE_FILE\": 100}','JSON',1,'JSON 对象：key=业务类型 code（见 FileBusinessType 枚举），value=体积上限 MB 数；缺失业务类型回退默认 10MB（StorageConfigReader.sizeLimitBytes 读取）',1,'admin','2026-07-03 21:09:51','admin','2026-07-03 21:09:51'),(8,'knowhub.file.type_whitelist','各业务类型白名单','{\"BLOG_BODY\": \"image/png,image/jpeg,image/gif,image/webp\", \"BLOG_COVER\": \"image/png,image/jpeg,image/gif,image/webp\", \"PLUGIN_JAR\": \".jar\", \"PROJECT_DOC\": \".docx,.pptx,.xlsx,.pdf\", \"PROJECT_PKG\": \".zip,.exe,.msi,.dmg,.deb,.rpm,.apk\", \"PROJECT_SRC\": \".zip,.tar,.gz,.7z,.rar\", \"AUDIT_VOUCHER\": \"image/png,image/jpeg,image/gif,image/webp,application/pdf\", \"RESOURCE_FILE\": \"\"}','JSON',1,'JSON 对象：key=业务类型 code，value=逗号分隔的扩展名/MIME 白名单；留空或缺失表示不限制（StorageConfigReader.typeWhitelist 读取）',1,'admin','2026-07-03 21:09:51','admin','2026-07-03 21:09:51'),(9,'knowhub.resource.review_enabled','资源审核开关','false','BOOLEAN',1,'资源发布是否需审核(true=开启:发布进入PENDING_REVIEW等管理员审核;false=直通PUBLISHED)。仅控制资源发布审核流,与\"前台分级推荐开关\"knowhub.portal.hierarchical.enabled 是两项独立配置。ResourceConfigReader.isReviewEnabled 读取',1,'admin','2026-07-07 14:36:53','admin','2026-08-18 21:01:33'),(11,'knowhub.project.review_enabled','项目审核开关','false','BOOLEAN',1,'项目发布是否需审核(true开启/false直通发布,ProjectConfigReader.isReviewEnabled读取)',1,'admin','2026-07-07 22:02:06','admin','2026-08-18 21:01:36'),(12,'knowhub.article.review_enabled','文章审核开关','false','BOOLEAN',1,'文章发布是否需审核(true开启/false直通发布,ArticleConfigReader.isReviewEnabled读取)',1,'admin','2026-07-08 22:23:22','admin','2026-08-18 21:01:42'),(14,'knowhub.audit.expense_approval_enabled','花销审批开关','true','BOOLEAN',1,'花销是否需审批(true开启阈值审批/false免审直接APPROVED,AuditConfigReader.isExpenseApprovalEnabled读取)',1,'admin','2026-08-12 19:40:18','admin','2026-08-12 19:40:18'),(15,'knowhub.audit.expense_approval_threshold','花销审批阈值','500.00','STRING',1,'花销审批阈值(元,STRING存\"500.00\"字符串,AuditConfigReader.getExpenseThreshold用new BigDecimal解析),低于阈值自动通过高于走PENDING',1,'admin','2026-08-12 19:40:18','admin','2026-08-12 19:40:18'),(16,'knowhub.audit.loan_approval_enabled','借出审批开关','true','BOOLEAN',1,'物品借出是否需审批(true开REQUEST→BORROWED/false直接BORROWED,AuditConfigReader.isLoanApprovalEnabled读取)',1,'admin','2026-08-12 19:40:18','admin','2026-08-12 19:40:18'),(17,'knowhub.audit.monthly_report_enabled','月度报表自动生成开关','true','BOOLEAN',1,'每月1日是否自动生成上月月报并通知负责人(true开/false关,关后仍可手动重算)',1,'admin','2026-08-12 19:40:18','admin','2026-08-12 19:40:18'),(18,'knowhub.audit.weekly_report_enabled','周记报表自动生成开关','true','BOOLEAN',1,'每周一是否自动生成上周周报并通知负责人(true开/false关,关后仍可手动重算)',1,'admin','2026-08-12 19:40:18','admin','2026-08-12 19:40:18'),(44,'sys.online.timeout','在线判定阈值（分钟）','30','NUMBER',1,'最后活跃时间超过该分钟数视为离线，与 token 有效期同口径',1,'admin','2026-08-16 20:35:45','admin','2026-08-16 20:35:45'),(45,'knowhub.review.notify_enabled','提审通知开关','true','BOOLEAN',1,'作品(博客/文章/项目/资源)发布进入待审核(PENDING_REVIEW)时是否按角色通知。true=按 notify_role_key 角色发站内通知;false=不发(默认)。ReviewNotifyConfigReader.isNotifyEnabled 读取',1,'admin','2026-08-17 00:49:03','admin','2026-08-17 00:50:44'),(46,'knowhub.review.notify_role_key','提审通知角色键','admin','STRING',1,'提审通知发送到的角色 role_key。持有该 role_key 且 sys_role/sys_user 双方有效(status=1,delete=0)的用户都收到站内通知。默认 admin(与 sys_role 内置 role_key 对齐)。ReviewNotifyConfigReader.getNotifyRoleKey 读取',1,'admin','2026-08-17 00:49:03','admin','2026-08-17 00:49:03');
/*!40000 ALTER TABLE `sys_config` ENABLE KEYS */;
UNLOCK TABLES;

