INSERT INTO `sys_job` VALUES (1,'文件对象GC','fileGcTask','gc','0 */10 * * * ?',NULL,1,'扫描超时未确认 PENDING 行与已软删行，DeleteObject 清 RustFS 对象 + 物理删元数据（原 @Scheduled fixedDelay 10min）','admin','2026-08-17 15:05:21','admin','2026-08-17 15:05:21'),(2,'博客审核对账','blogReviewReconcileTask','reconcile','0 */5 * * * ?',NULL,1,'审核开关关闭后扫描遗留待审博客批量放行（原 @Scheduled fixedDelay 5min）','admin','2026-08-17 15:05:21','admin','2026-08-17 15:05:21'),(3,'文章审核对账','articleReviewReconcileTask','reconcile','0 */5 * * * ?',NULL,1,'审核开关关闭后扫描遗留待审文章批量放行（原 @Scheduled fixedDelay 5min）','admin','2026-08-17 15:05:21','admin','2026-08-17 15:05:21'),(4,'资源审核对账','resourceReviewReconcileTask','reconcile','0 */5 * * * ?',NULL,1,'审核开关关闭后扫描遗留待审资源批量放行（原 @Scheduled fixedDelay 5min）','admin','2026-08-17 15:05:22','admin','2026-08-17 15:05:22'),(5,'项目审核对账','projectReviewReconcileTask','reconcile','0 */5 * * * ?',NULL,1,'审核开关关闭后扫描遗留待审项目批量放行（原 @Scheduled fixedDelay 5min）','admin','2026-08-17 15:05:22','admin','2026-08-17 15:05:22'),(6,'借出逾期对账','auditLoanOverdueTask','scanOverdue','0 */30 * * * ?',NULL,1,'扫描 status=BORROWED 且 expected_return_date < now 的借出置 OVERDUE（原 @Scheduled fixedDelay 30min）','admin','2026-08-17 15:05:22','admin','2026-08-17 15:05:22'),(7,'周记报表生成','auditWeeklyReportTask','generateWeeklyReport','0 10 0 ? * MON',NULL,1,'每周一 00:10 生成上周周报（knowhub.audit.weekly_report_enabled 开启时才生成，原 @Scheduled cron 0 10 0 ? * MON）','admin','2026-08-17 15:05:22','admin','2026-08-17 15:05:22'),(8,'月度报表生成','auditMonthlyReportTask','generateMonthlyReport','0 10 0 1 * *',NULL,1,'每月1日 00:10 生成上月月报（knowhub.audit.monthly_report_enabled 开启时才生成，原 @Scheduled cron 0 10 0 1 * *）','admin','2026-08-17 15:05:22','admin','2026-08-17 15:05:22');
