--
-- Table structure for table `sys_notice`
--

DROP TABLE IF EXISTS `sys_notice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_notice` (
  `notice_id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息主键',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '正文内容',
  `notice_type` varchar(32) NOT NULL DEFAULT 'NOTICE' COMMENT '消息类型：NOTICE公告 NOTIFY通知 REMIND提醒',
  `level` varchar(32) NOT NULL DEFAULT 'NORMAL' COMMENT '消息级别：NORMAL普通 IMPORTANT重要 URGENT紧急',
  `publish_scope` varchar(32) NOT NULL DEFAULT 'ALL' COMMENT '发布范围：ALL全员 GROUP分组',
  `status` varchar(32) NOT NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT草稿 PUBLISHED已发布 REVOKED已撤回',
  `is_top` tinyint NOT NULL DEFAULT '0' COMMENT '是否置顶：0否 1是',
  `need_confirm` tinyint NOT NULL DEFAULT '0' COMMENT '是否需要确认：0否 1是',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间',
  `route_path` varchar(255) DEFAULT NULL COMMENT '前端路由路径',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete` tinyint NOT NULL DEFAULT '0' COMMENT '删除标记：0未删除 1已删除',
  PRIMARY KEY (`notice_id`),
  KEY `idx_notice_type` (`notice_type`),
  KEY `idx_notice_status` (`status`),
  KEY `idx_notice_scope` (`publish_scope`),
  KEY `idx_notice_publish_time` (`publish_time`),
  KEY `idx_notice_delete` (`delete`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='消息通知主表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_notice`
--

LOCK TABLES `sys_notice` WRITE;
/*!40000 ALTER TABLE `sys_notice` DISABLE KEYS */;
INSERT INTO `sys_notice` VALUES (4,'知枢 · knowhub 火热内测中，欢迎大家前来记录学习时光！','欢迎来到 知枢 knowhub —— 一个面向知识沉淀与项目展示的开源社区平台。在正式发布前，我们邀请你提前体验并帮忙打磨它。\n\n## 你可以做什么\n- 写博客：记录技术笔记与思考，支持审核发布\n- 建项目：展示个人/团队项目，附文件树与成员协作\n- 传资源：分享课件、工具、源码等学习材料\n- 读文档：按章节组织长文，沉浸式阅读\n- 看公告 / 全局搜索：跨内容检索，社区动态一站直达\n## 当前说明\n- 部分功能仍处于灰度阶段，数据可能被重置，请勿存放重要内容。\n- AI 日报 即将上线，敬请期待。\n- 可能遇到 bug、错别字或加载异常，属于正常现象。\n## 期待你的反馈\n使用中遇到任何问题或有改进建议，请通过以下方式告诉我们：\n\n- 直接在群里 @ 维护者\n- 提 issue 到项目仓库\n- 或私下戳我\n你的每一条反馈都在让知枢变得更好。感谢参与内测，enjoy！','NOTICE','NORMAL','ALL','PUBLISHED',0,0,'2026-08-09 20:47:04',NULL,NULL,'','admin','2026-08-09 20:46:49','admin','2026-08-09 20:47:04',0),(5,'admin 回复了你的评论','还真是','NOTIFY','NORMAL','USER','PUBLISHED',0,0,'2026-08-14 22:15:44',NULL,'/resource/4',NULL,'admin','2026-08-14 22:15:44','admin','2026-08-14 22:15:44',0),(6,'有新的项目邀请','用户「admin」邀请你加入项目《测试》，请前往「我的协作」处理。','NOTIFY','NORMAL','USER','PUBLISHED',0,0,'2026-08-15 20:37:23',NULL,'/collaboration?tab=received-invites',NULL,'system','2026-08-15 20:37:22','system','2026-08-15 20:37:22',0),(7,'项目新成员加入','用户「rookie」已接受邀请加入项目《测试》。','NOTIFY','NORMAL','USER','PUBLISHED',0,0,'2026-08-15 20:37:41',NULL,'/project/3',NULL,'system','2026-08-15 20:37:40','system','2026-08-15 20:37:40',0),(8,'有新的文章贡献申请','用户「rookie」申请成为你的文章《知枢说明》的贡献者，请前往「我的协作」处理。','NOTIFY','NORMAL','USER','PUBLISHED',0,0,'2026-08-15 21:18:56',NULL,'/profile?tab=collaboration',NULL,'system','2026-08-15 21:18:55','system','2026-08-15 21:18:55',0),(9,'你的文章贡献申请未通过','你申请文章《null》的贡献者未通过。原因：暂不接受申请','NOTIFY','NORMAL','USER','PUBLISHED',0,0,'2026-08-15 21:19:48',NULL,'/profile?tab=collaboration',NULL,'system','2026-08-15 21:19:48','system','2026-08-15 21:19:48',0),(10,'有新的文章贡献申请','用户「rookie」申请成为你的文章《知枢说明》的贡献者，请前往「我的协作」处理。','NOTIFY','NORMAL','USER','PUBLISHED',0,0,'2026-08-15 21:24:14',NULL,'/profile?tab=collaboration',NULL,'system','2026-08-15 21:24:14','system','2026-08-15 21:24:14',0),(11,'你的文章贡献申请已通过','你已成为文章《null》的贡献者，可前往该文章提交章节。','NOTIFY','NORMAL','USER','PUBLISHED',0,0,'2026-08-15 21:24:37',NULL,'/arti